{age}
{email}
</>
      );
 })}
    <div>
      <input type="text" placeholder='Name'onChange={e=>setName(e(e.target.value))} />
      <input type="number" placeholder='Age'onChange={e=>setAge(e(e.target.value))} />
      <input type="text" placeholder="Email"onChange={e=>setEmail(e(e.target.value))} />
      <button onClick={createUser}>Create User</button>
    </div>

    </div>
  );
}

export default App;
